# --- Negative: months out of [1, 24] 422s at the route's own bound check ----------


@pytest.fixture
def scratch_app() -> FastAPI:
    fastapi_app = FastAPI()
    fastapi_app.include_router(client_portal_router, prefix="/api")
    return fastapi_app


@pytest.fixture
def client(scratch_app, db_factory):
    db = db_factory()
    client_user = make_client(db, name="Cathy Client")
    db.close()

    def _override_get_db():
        session = db_factory()
        try:
            yield session
        finally:
            session.close()

    scratch_app.dependency_overrides[get_db] = _override_get_db
    scratch_app.dependency_overrides[get_current_client_user] = lambda: client_user
    try:
        yield TestClient(scratch_app)
    finally:
        scratch_app.dependency_overrides.clear()


@pytest.mark.parametrize("months", [0, 25])
def test_portfolio_history_out_of_bounds_months_returns_422(client, months):
    resp = client.get(f"/api/client/portfolio/history?months={months}")
    assert resp.status_code == 422


def test_portfolio_history_in_bounds_months_returns_200(client):
    resp = client.get("/api/client/portfolio/history?months=6")
    assert resp.status_code == 200, resp.text
    assert len(resp.json()) == 6


